<?php

require_once __DIR__ . '/Lang.php';

/** UI explanations for the fields supported by ProtocolOptions, not arbitrary core settings. */
final class ProtocolOptionHelp
{
    public static function text(string $protocol, string $path): string
    {
        $t = static fn(string $ru, string $en) => Lang::t($ru, $en);
        if ($protocol === 'masque') return match ($path) {
            'client', 'client.http' => $t('h3: HTTP/3 через UDP (по умолчанию); h2: HTTP/2 через TCP. Оба передают TCP и UDP приложений. Требуется Xray 26.9.30+. После изменения скачайте профиль заново.',
                'h3: HTTP/3 over UDP (default); h2: HTTP/2 over TCP. Both carry application TCP and UDP. Requires Xray 26.9.30+. Download the profile again after a change.'),
            'client.connections' => $t('XMUX: сколько туннелей CONNECT-IP клиент держит одновременно и распределяет между ними соединения, 1–4. Каждый туннель — отдельное QUIC- или TCP-соединение и отдельный адрес в пуле сервера. Работает в Xray 26.10.17+ и форке 26.10.13+, старые клиенты настройку не учитывают. Сброс — один туннель.',
                'XMUX: how many CONNECT-IP tunnels the client keeps at once and spreads connections across, 1–4. Each tunnel is a separate QUIC or TCP connection and a separate address in the server pool. Works in Xray 26.10.17+ and fork 26.10.13+; older clients ignore the setting. Reset means one tunnel.'),
            'client.reuse' => $t('XMUX: сколько секунд туннель принимает новые соединения, затем клиент открывает новый; начатые соединения доживают в старом. Число или диапазон 60–86400, например 1800-3000 (так ядро делает по умолчанию). Работает в Xray 26.10.17+ и форке 26.10.13+.',
                'XMUX: how many seconds a tunnel accepts new connections before the client opens a new one; started connections finish in the old one. A number or range 60–86400, e.g. 1800-3000 (the core default). Works in Xray 26.10.17+ and fork 26.10.13+.'),
            'noise', 'noise.enabled' => $t('UDP finalmask на сервере MASQUE и в профиле клиента h3. По умолчанию выключен; включение без своего списка выбирает динамический exp. HTTP/2 не использует UDP-маскировку. Дополнительные пакеты увеличивают трафик и не гарантируют обход блокировок.',
                'UDP finalmask on the MASQUE server and in the h3 client profile. Off by default; enabling it without your own list selects the dynamic exp. HTTP/2 does not use UDP masking. Extra packets increase traffic and do not guarantee getting around blocks.'),
            'noise.reset' => $t('Время без исходящих UDP-пакетов к адресу, после которого следующая отправка повторяет шум: число или диапазон 1–86400 секунд. По умолчанию 60-120. При непрерывном трафике это не периодический таймер.',
                'Time without outgoing UDP packets to an address after which the next send repeats the noise: a number or range of 1–86400 seconds. Default 60-120. With continuous traffic this is not a periodic timer.'),
            'noise.packets' => $t('JSON, до 8 пакетов по 1400 байт: [{"type":"exp","packet":"<b 0d0a><t><c><n><rc 20-40>","delay":"1-3"}]. Типы: rand, str, hex, base64, exp. exp: <b hex>, <r N-M>, <rc N-M> буквы, <rd N-M> цифры, <t> время, <c> счётчик, <n> nonce. delay 0–1000 мс. Сброс возвращает динамический шаблон.',
                'JSON, up to 8 packets of 1400 bytes: [{"type":"exp","packet":"<b 0d0a><t><c><n><rc 20-40>","delay":"1-3"}]. Types: rand, str, hex, base64, exp. exp: <b hex>, <r N-M>, <rc N-M> letters, <rd N-M> digits, <t> time, <c> counter, <n> nonce. delay 0–1000 ms. Reset restores the dynamic template.'),
            default => $t('Настройки MASQUE применяются к отдельному сервису; выбор версии основного Xray на него не влияет.',
                'MASQUE settings apply to a separate service; the main Xray version choice does not affect it.'),
        };
        $field = substr($path, (int) strrpos('.' . $path, '.'));
        $text = match ($field) {
            'server' => $t('Параметры ядра на VPN-сервере. Сохраняются и применяются автоматически; изменение может прервать соединения этого протокола.',
                'Core parameters on the VPN server. They are saved and applied automatically; a change may interrupt this protocol\'s connections.'),
            'client' => $t('Общие параметры совместимых клиентов. Сохранение меняет выдаваемые профили; на устройстве обновите подписку или импортируйте профиль заново.',
                'Shared parameters of compatible clients. Saving changes the issued profiles; on the device refresh the subscription or import the profile again.'),
            'singbox' => $t('Эти параметры попадают только в JSON sing-box. Они не меняют сервер и настройки Mihomo.',
                'These parameters go only into the sing-box JSON. They do not change the server or the Mihomo settings.'),
            'mihomo' => $t('Эти параметры попадают только в профили Mihomo. Они не меняют сервер и sing-box.',
                'These parameters go only into Mihomo profiles. They do not change the server or sing-box.'),
            'native' => $t('Настройки отдельного приложения Mieru: локальные порты, MTU и журнал. Не применяются к Mihomo; полный набор переносится в нативный JSON.',
                'Settings of the standalone Mieru app: local ports, MTU and log. They do not apply to Mihomo; the full set goes into the native JSON.'),
            'log_level', 'loggingLevel' => $t('Подробность журнала: trace/TRACE — все подробности, debug/DEBUG — диагностика, info/INFO — обычные события, warn/WARN — предупреждения, error/ERROR — ошибки, fatal/FATAL — критические ошибки, panic — только аварии. Подробный журнал занимает больше места.',
                'Log detail: trace/TRACE: everything, debug/DEBUG: diagnostics, info/INFO: ordinary events, warn/WARN: warnings, error/ERROR: errors, fatal/FATAL: critical errors, panic: crashes only. A detailed log takes more space.'),
            'dns_server' => $t('IP DNS-сервера, через который VPN-сервер разрешает имена назначений. Это не DNS на клиентском устройстве.',
                'IP of the DNS server the VPN server uses to resolve destination names. This is not the DNS on the client device.'),
            'tcp_fast_open', 'tfo' => $t('TCP Fast Open: разрешает отправить первые данные при установлении TCP-соединения. Выключено — обычное соединение. Требуется поддержка ОС и сети.',
                'TCP Fast Open: allows sending the first data while the TCP connection is being established. Off: an ordinary connection. Needs OS and network support.'),
            'tcp_multi_path', 'mptcp' => $t('Multipath TCP: разрешает одному соединению использовать несколько сетевых путей. Выключено — обычный TCP. Требуется поддержка MPTCP обеими сторонами и ОС.',
                'Multipath TCP: allows one connection to use several network paths. Off: ordinary TCP. Needs MPTCP support on both sides and in the OS.'),
            'disable_tcp_keep_alive' => $t('Включено — отключить TCP keepalive-пробы; выключено — разрешить их. Пробы помогают обнаружить пропавшее соединение.',
                'On: disable TCP keepalive probes; off: allow them. Probes help detect a lost connection.'),
            'tcp_keep_alive' => $t('Сколько соединение TCP может бездействовать до первой keepalive-пробы. Не действует при отключённом keepalive.',
                'How long a TCP connection may stay idle before the first keepalive probe. No effect when keepalive is disabled.'),
            'tcp_keep_alive_interval' => $t('Интервал между TCP keepalive-пробами. Меньше — быстрее проверка связи, больше служебных пакетов.',
                'Interval between TCP keepalive probes. Lower: faster liveness check, more service packets.'),
            'padding_scheme' => $t('Правила дополнения первых пакетов AnyTLS до заданных размеров. JSON-массив, например ["stop=2","0=30-30","1=100-400"]. stop задаёт конец схемы; строки N=min-max — размеры для пакета N. Увеличивает трафик; сброс возвращает штатную схему.',
                'Rules for padding the first AnyTLS packets to given sizes. A JSON array, e.g. ["stop=2","0=30-30","1=100-400"]. stop ends the scheme; N=min-max lines are sizes for packet N. Increases traffic; reset restores the standard scheme.'),
            'tls' => $t('Согласование TLS: версии, ALPN и криптографические параметры. Настройки клиента и сервера должны быть совместимы; TUIC и ShadowTLS требуют TLS 1.3.',
                'TLS negotiation: versions, ALPN and cryptographic parameters. Client and server settings must be compatible; TUIC and ShadowTLS require TLS 1.3.'),
            'alpn' => $t('Протоколы внутри TLS в порядке предпочтения, например ["h3"] для TUIC, ["http/1.1"] для сайта прикрытия AnyTLS. Нужен хотя бы один общий вариант у клиента и сервера.',
                'Protocols inside TLS in order of preference, e.g. ["h3"] for TUIC, ["http/1.1"] for an AnyTLS cover site. The client and server need at least one option in common.'),
            'min_version' => $t('Самая старая разрешённая версия TLS: 1.2 или 1.3. Повышение минимума исключает старые клиенты; для TUIC и ShadowTLS доступна только 1.3.',
                'The oldest allowed TLS version: 1.2 or 1.3. Raising the minimum excludes old clients; TUIC and ShadowTLS allow only 1.3.'),
            'max_version' => $t('Самая новая разрешённая версия TLS. 1.2 ограничивает соединение TLS 1.2; 1.3 разрешает TLS 1.3. Минимум не должен быть выше максимума.',
                'The newest allowed TLS version. 1.2 limits the connection to TLS 1.2; 1.3 allows TLS 1.3. The minimum must not exceed the maximum.'),
            'cipher_suites' => $t('Разрешённые наборы шифров TLS 1.2: AES-GCM или ChaCha20-Poly1305; RSA/ECDSA должны подходить сертификату. На наборы TLS 1.3 этот список не влияет.',
                'Allowed TLS 1.2 cipher suites: AES-GCM or ChaCha20-Poly1305; RSA/ECDSA must match the certificate. This list does not affect TLS 1.3 suites.'),
            'curve_preferences' => $t('Группы обмена ключами TLS в порядке предпочтения. P256/P384/P521 и X25519 — эллиптические кривые; X25519MLKEM768 — гибрид с постквантовым ML-KEM. Клиент и сервер должны поддерживать выбранную группу.',
                'TLS key exchange groups in order of preference. P256/P384/P521 and X25519 are elliptic curves; X25519MLKEM768 is a hybrid with post-quantum ML-KEM. The client and server must support the selected group.'),
            'handshake_timeout' => $t('Предельное время согласования TLS. По истечении попытка соединения прекращается.',
                'The time limit for TLS negotiation. When it runs out, the connection attempt stops.'),
            'fingerprint' => $t('Вид первого TLS-сообщения ClientHello, отправляемого клиентом. Меняет отпечаток рукопожатия, но не превращает VPN в браузер и не гарантирует обход блокировок.',
                'The shape of the first TLS ClientHello message the client sends. It changes the handshake fingerprint but does not turn the VPN into a browser or guarantee getting around blocks.'),
            'idle_session_check_interval' => $t('Как часто AnyTLS проверяет неиспользуемые сессии для закрытия. Задавайте целые секунды, например 30s.',
                'How often AnyTLS checks unused sessions to close them. Use whole seconds, e.g. 30s.'),
            'idle_session_timeout' => $t('Как долго AnyTLS хранит неиспользуемую сессию перед закрытием. Повторное использование сокращает задержку новых подключений.',
                'How long AnyTLS keeps an unused session before closing it. Reuse cuts the latency of new connections.'),
            'min_idle_session' => $t('Сколько свободных сессий AnyTLS сохранять при очистке. 0 разрешает закрыть все; большее число удерживает больше соединений.',
                'How many idle AnyTLS sessions to keep during cleanup. 0 allows closing all; a larger number keeps more connections.'),
            'client_metadata' => $t('Текстовая метка клиента, передаваемая серверу AnyTLS в поддерживающих её клиентах. Не является паролем и не изменяет разрешения доступа.',
                'A text label of the client sent to the AnyTLS server by clients that support it. It is not a password and does not change access permissions.'),
            'udp' => $t('Разрешить UDP приложений через AnyTLS. Выключено — остаётся TCP: Mihomo отключает UDP в профиле, сервер AnyTLS также отклоняет UDP. В общей подписке это не затрагивает UDP других протоколов и DNS шаблона.',
                'Allow application UDP through AnyTLS. Off: TCP only; Mihomo disables UDP in the profile and the AnyTLS server rejects UDP too. In the shared subscription this does not affect UDP of other protocols or the template DNS.'),
            'connect_timeout' => str_starts_with($path, 'server.handshake.')
                ? $t('Сколько сервер ShadowTLS ждёт подключения к сайту прикрытия.', 'How long the ShadowTLS server waits for the connection to the cover site.')
                : $t('Сколько клиент sing-box ждёт установления соединения с VPN-сервером.', 'How long the sing-box client waits for the connection to the VPN server.'),
            'certificate_public_key_sha256' => $t('Дополнительная проверка SHA-256 публичного ключа TLS-сертификата. Если ключ сертификата сменится, обновите пин в профиле. Обычная проверка сертификата сохраняется.',
                'An extra SHA-256 check of the TLS certificate public key. If the certificate key changes, update the pin in the profile. The ordinary certificate check stays.'),
            'fragment' => $t('Разбить TLS-рукопожатие клиента на TCP-сегменты. Может увеличить задержку; сначала попробуйте record_fragment. Выключено — не запрашивать это разбиение.',
                'Split the client TLS handshake into TCP segments. May increase latency; try record_fragment first. Off: do not request this split.'),
            'fragment_fallback_delay' => $t('Задержка запасного способа фрагментации TLS, когда автоматический способ неприменим. Используется вместе с fragment.',
                'Delay of the fallback TLS fragmentation method when the automatic one does not apply. Used together with fragment.'),
            'record_fragment' => $t('Разбить TLS-рукопожатие клиента на несколько TLS-записей. Обычно требует меньше накладных расходов, чем TCP fragment.',
                'Split the client TLS handshake into several TLS records. Usually has less overhead than TCP fragment.'),
            'spoof' => $t('Домен в подставном ClientHello перед настоящим рукопожатием. Только sing-box на клиенте; нужны сетевые права ОС (на Linux CAP_NET_RAW и CAP_NET_ADMIN). Реальный SNI и проверка TLS сохраняются.',
                'A domain in a decoy ClientHello sent before the real handshake. Only sing-box on the client; needs OS network privileges (CAP_NET_RAW and CAP_NET_ADMIN on Linux). The real SNI and TLS verification stay.'),
            'spoof_method' => $t('Как сделать подставной TCP-сегмент неприемлемым для настоящего сервера. Сначала задайте spoof; поддержка зависит от ОС клиента.',
                'How to make the decoy TCP segment unacceptable to the real server. Set spoof first; support depends on the client OS.'),
            'ip-version' => $t('Какие IP-адреса использовать при разрешении имени сервера в Mihomo.',
                'Which IP addresses to use when Mihomo resolves the server name.'),
            'disable-reuse' => $t('Включено — отключить повторное использование сессий AnyTLS в Mihomo. Выключено — разрешить повторное использование и уменьшить число новых рукопожатий.',
                'On: disable AnyTLS session reuse in Mihomo. Off: allow reuse and reduce the number of new handshakes.'),
            'udp_fragment' => $t('Разрешить IP-фрагментацию исходящих UDP-пакетов сокета. Это не TUIC udp_mode и не TLS fragment. Работа зависит от ОС и пути до сервера.',
                'Allow IP fragmentation of the socket\'s outgoing UDP packets. This is neither TUIC udp_mode nor TLS fragment. Behaviour depends on the OS and the path to the server.'),
            'udp_timeout' => $t('Сколько хранить неактивное UDP-состояние на сервере. После таймаута следующему обмену потребуется новое состояние.',
                'How long the server keeps inactive UDP state. After the timeout the next exchange needs new state.'),
            'idle_timeout' => $t('Таймаут простоя QUIC-соединения. После его истечения соединение закрывается.',
                'Idle timeout of the QUIC connection. When it expires, the connection closes.'),
            'keep_alive_period' => $t('Интервал служебных QUIC-пакетов для поддержания соединения и NAT. Меньший интервал увеличивает фоновый трафик.',
                'Interval of QUIC keepalive packets that keep the connection and NAT alive. A shorter interval increases background traffic.'),
            'stream_receive_window', 'recv-window' => $t('Максимальное окно приёма одного QUIC-потока в байтах. Больше — полезно на быстрых каналах с задержкой, но требует больше памяти.',
                'Maximum receive window of one QUIC stream in bytes. Larger helps on fast links with latency but needs more memory.'),
            'connection_receive_window', 'recv-window-conn' => $t('Максимальное общее окно приёма QUIC-соединения в байтах. Оно не должно быть меньше окна одного потока.',
                'Maximum total receive window of the QUIC connection in bytes. It must not be smaller than the window of one stream.'),
            'max_concurrent_streams', 'max-open-streams' => $t('Предел одновременно открытых потоков QUIC. Больше — больше параллельных запросов и расход памяти.',
                'Limit of concurrently open QUIC streams. Higher: more parallel requests and more memory use.'),
            'initial_packet_size' => $t('Начальный размер исходящего QUIC-пакета в байтах. Слишком большой размер на узком MTU может помешать подключению.',
                'Initial size of an outgoing QUIC packet in bytes. Too large a size on a narrow MTU may prevent connecting.'),
            'disable_path_mtu_discovery', 'disable-mtu-discovery' => $t('Включено — отключить поиск подходящего размера QUIC-пакетов по пути. Выключено — разрешить автоматический подбор MTU.',
                'On: disable path MTU discovery for QUIC packets. Off: allow automatic MTU selection.'),
            'auth_timeout' => $t('Сколько сервер TUIC ждёт успешной авторизации клиента перед закрытием соединения.',
                'How long the TUIC server waits for successful client authentication before closing the connection.'),
            'heartbeat' => $t('Интервал heartbeat-пакетов клиента TUIC для поддержания сеанса. Меньше — больше служебного трафика.',
                'Interval of TUIC client heartbeat packets that keep the session alive. Lower: more service traffic.'),
            'zero_rtt_handshake' => $t('Раннее согласование TUIC (0-RTT): уменьшает ожидание, но повышает риск повторного воспроизведения ранних запросов. По умолчанию выключено.',
                'Early TUIC negotiation (0-RTT): reduces waiting but raises the risk of early requests being replayed. Off by default.'),
            'udp_over_stream' => $t('Включено — UDP приложений передаётся в надёжном потоке QUIC с повторной доставкой потерь. Выключено — используется выбранный native/quic. Может увеличивать задержку; транспорт до сервера остаётся UDP.',
                'On: application UDP is carried in a reliable QUIC stream with retransmission of losses. Off: the selected native/quic is used. May increase latency; the transport to the server stays UDP.'),
            'request-timeout' => $t('Таймаут запроса TUIC в Mihomo, в миллисекундах.',
                'TUIC request timeout in Mihomo, in milliseconds.'),
            'max-udp-relay-packet-size' => $t('Максимальный размер пакета для TUIC UDP relay в Mihomo, в байтах. Меняет упаковку UDP, а не порт сервера.',
                'Maximum packet size for TUIC UDP relay in Mihomo, in bytes. It changes UDP packing, not the server port.'),
            'fast-open' => $t('Включено — Mihomo начинает установление TUIC лениво, при первом чтении/записи. Выключено — при создании соединения. Это не TCP Fast Open и не переключатель 0-RTT.',
                'On: Mihomo establishes TUIC lazily, on the first read/write. Off: when the connection is created. This is neither TCP Fast Open nor the 0-RTT switch.'),
            'cwnd' => $t('Начальное окно перегрузки TUIC в Mihomo, в пакетах. Большое значение ускоряет старт, но может усилить потери; учитывается поддерживающим его алгоритмом.',
                'Initial TUIC congestion window in Mihomo, in packets. A large value speeds up the start but may increase losses; honoured by algorithms that support it.'),
            'bbr-profile' => $t('Режим BBR в Mihomo: применяется при выбранном алгоритме bbr.',
                'BBR mode in Mihomo: applies when the bbr algorithm is selected.'),
            'max-datagram-frame-size' => $t('Максимальный размер QUIC DATAGRAM, объявляемый Mihomo, в байтах. Влияет на передачу UDP внутри QUIC.',
                'Maximum QUIC DATAGRAM size advertised by Mihomo, in bytes. Affects UDP transfer inside QUIC.'),
            'handshake' => $t('Подключение сервера ShadowTLS к сайту прикрытия: порт и параметры TCP. Это отдельное соединение, не внешний VPN-порт.',
                'The ShadowTLS server\'s connection to the cover site: port and TCP parameters. This is a separate connection, not the external VPN port.'),
            'server_port' => $t('TLS-порт сайта прикрытия, к которому подключается ShadowTLS. Для собственного сайта фиксирован 10443. Не меняет порт входа пользователей.',
                'TLS port of the cover site ShadowTLS connects to. Fixed at 10443 for your own site. It does not change the users\' entry port.'),
            'multiplex' => $t('Несколько потоков внутреннего Shadowsocks в одном соединении. Настройка переносится на сервер и клиентов; обновите их профили вместе. По умолчанию выключено, при включении выбран smux.',
                'Several inner Shadowsocks streams in one connection. The setting is carried to the server and the clients; update their profiles together. Off by default; smux is selected when enabled.'),
            'enabled' => $t('Включить объединение потоков Shadowsocks. Выключено — отдельные соединения. После смены обновите профили клиентов.',
                'Enable Shadowsocks stream multiplexing. Off: separate connections. Update client profiles after a change.'),
            'padding' => $path === 'multiplex.padding'
                ? $t('Включено — дополнять мультиплексированные потоки служебными байтами; сервер потребует такой же режим клиента. Выключено — без дополнения.',
                    'On: pad multiplexed streams with service bytes; the server will require the same mode from the client. Off: no padding.')
                : $t('Дополнительные случайные байты в середине и конце сегмента Mieru. Меняют размеры пакетов и увеличивают трафик.',
                    'Extra random bytes in the middle and at the end of a Mieru segment. They change packet sizes and increase traffic.'),
            'protocol' => $t('Формат объединения потоков: smux — лёгкий мультиплексор (штатный выбор бота), yamux — другой формат мультиплексирования, h2mux — на основе HTTP/2. Для h2mux нужен клиент с исправлением GO-2026-4918; официальный Mihomo 1.19.34 содержит старый x/net.',
                'Stream multiplexing format: smux, a light multiplexer (the bot\'s standard choice); yamux, another multiplexing format; h2mux, based on HTTP/2. h2mux needs a client with the GO-2026-4918 fix; the official Mihomo 1.19.34 ships an old x/net.'),
            'max_connections' => $t('Максимум соединений для мультиплексирования. В каждом могут передаваться несколько потоков.',
                'Maximum connections for multiplexing. Each may carry several streams.'),
            'min_streams' => $t('Минимум потоков в соединении перед открытием следующего. Не задавайте одновременно с ненулевым max_streams.',
                'Minimum streams in a connection before the next one opens. Do not set together with a non-zero max_streams.'),
            'max_streams' => $t('Предел потоков в одном соединении перед открытием следующего. 0 — без этого ограничения. Не задавайте одновременно с ненулевым min_streams.',
                'Limit of streams in one connection before the next one opens. 0: no such limit. Do not set together with a non-zero min_streams.'),
            'mtu' => $t('MTU транспорта Mieru в байтах. Меньший размер полезен на путях с ограниченным MTU; этот параметр не переносится в Mihomo.',
                'Mieru transport MTU in bytes. A smaller size helps on paths with a limited MTU; this parameter is not carried to Mihomo.'),
            'advancedSettings' => $t('Дополнительные серверные параметры Mieru: журнал метрик, проверка подсказки пользователя и тайм-аут простоя TCP.',
                'Additional Mieru server parameters: the metrics log, the user hint check and the TCP idle timeout.'),
            'metricsLoggingInterval' => $t('Как часто Mieru пишет метрики в журнал. Короткий интервал создаёт больше записей.',
                'How often Mieru writes metrics to the log. A short interval creates more entries.'),
            'userHintIsMandatory' => $t('Включено — Mieru требует подсказку идентификации пользователя от клиента; старые клиенты без неё не подключатся. Выключено — подсказка необязательна.',
                'On: Mieru requires a user identification hint from the client; old clients without it will not connect. Off: the hint is optional.'),
            'tcpIdleTimeout' => $t('Mieru 3.39.0+: закрыть серверное TCP-соединение, если в обе стороны нет данных заданное время. От 1m до 24h, например 15m. Активность любого потока или служебные пакеты клиента продлевают время. UDP-транспорт не затрагивается. По умолчанию выключено; «Сбросить» выключает тайм-аут. Короткое значение может прервать простаивающий туннель; профили клиентов менять не нужно.',
                'Mieru 3.39.0+: close a server TCP connection after no data in either direction for this duration. From 1m to 24h, e.g. 15m. Activity on any stream or client control packets refreshes the timer. UDP transport is unaffected. Off by default; Reset disables the timeout. A short value can interrupt an idle tunnel; client profiles need no changes.'),
            'dns' => $t('Разрешение имён на сервере Mieru: выбор IPv4/IPv6 и точечные соответствия доменов адресам.',
                'Name resolution on the Mieru server: IPv4/IPv6 choice and specific domain-to-address mappings.'),
            'dualStack' => $t('Как сервер Mieru выбирает адрес, если DNS возвращает IPv4 и IPv6.',
                'How the Mieru server picks an address when DNS returns both IPv4 and IPv6.'),
            'hosts' => $t('Локальные соответствия домен → IP для DNS Mieru, например {"example.com":"203.0.113.10"}. Для этих имён применяется заданный адрес.',
                'Local domain → IP mappings for Mieru DNS, e.g. {"example.com":"203.0.113.10"}. The given address is used for these names.'),
            'trafficPattern' => $t('Рисунок отправляемого трафика Mieru: разбиение, префиксы и дополнение. Клиент и сервер настраивают свой исходящий трафик независимо.',
                'The shape of the traffic Mieru sends: splitting, prefixes and padding. The client and server configure their outgoing traffic independently.'),
            'seed' => $t('Число для воспроизводимого выбора не заданных явно параметров рисунка Mieru. Одинаковый seed сохраняет выбор; это не пароль и не ключ шифрования.',
                'A number for reproducible selection of the Mieru pattern parameters that are not set explicitly. The same seed keeps the choice; it is neither a password nor an encryption key.'),
            'unlockAll' => $t('Включено — автоматический выбор рисунка Mieru может использовать все варианты, включая затратные. Выключено — только ограниченный набор. Явно заданные поля доступны в обоих режимах.',
                'On: automatic selection of the Mieru pattern may use all options, including costly ones. Off: only a limited set. Explicitly set fields are available in both modes.'),
            'tcpFragment' => $t('Дополнительное разбиение TCP-трафика Mieru на фрагменты с паузами. Может повысить задержку.',
                'Extra splitting of Mieru TCP traffic into fragments with pauses. May increase latency.'),
            'enable' => $t('Включить дополнительное TCP-разбиение Mieru. Выключено — без этого разбиения.',
                'Enable extra Mieru TCP splitting. Off: no such splitting.'),
            'maxSleepMs' => $t('Максимальная пауза между TCP-фрагментами Mieru, в миллисекундах. 0 — без дополнительной паузы.',
                'Maximum pause between Mieru TCP fragments, in milliseconds. 0: no extra pause.'),
            'nonce' => $t('Внешний вид первых байтов nonce Mieru. Меняет наблюдаемый префикс пакета; не задаёт пароль пользователя.',
                'The appearance of the first bytes of the Mieru nonce. It changes the observable packet prefix; it does not set the user password.'),
            'type' => $t('Способ выбора префикса nonce Mieru.', 'How the Mieru nonce prefix is chosen.'),
            'applyToAllUDPPacket' => $t('Включено — рисунок nonce применяется ко всем UDP-пакетам Mieru. Выключено — только к первому пакету.',
                'On: the nonce pattern applies to all Mieru UDP packets. Off: only to the first packet.'),
            'minLen' => $t('Минимум изменяемых байтов префикса nonce, от 0 до 12. Используется в PRINTABLE/PRINTABLE_SUBSET; игнорируется в RANDOM/FIXED.',
                'Minimum number of nonce prefix bytes to change, 0 to 12. Used in PRINTABLE/PRINTABLE_SUBSET; ignored in RANDOM/FIXED.'),
            'maxLen' => $t('Максимум изменяемых байтов префикса nonce, до 12. Должен быть не меньше minLen. Используется в PRINTABLE/PRINTABLE_SUBSET.',
                'Maximum number of nonce prefix bytes to change, up to 12. Must not be less than minLen. Used in PRINTABLE/PRINTABLE_SUBSET.'),
            'customHexStrings' => $t('Варианты префикса nonce в HEX без 0x, например ["010203","aabb"]. В режиме FIXED каждый раз выбирается один из списка; в остальных режимах список не используется.',
                'Nonce prefix options in HEX without 0x, e.g. ["010203","aabb"]. In FIXED mode one of the list is chosen each time; other modes do not use the list.'),
            'maxMiddlePaddingLen' => $t('Максимум дополнительных байтов в середине сегмента Mieru. 0 отключает это дополнение; сброс возвращает выбор ядра.',
                'Maximum extra bytes in the middle of a Mieru segment. 0 disables this padding; reset restores the core\'s choice.'),
            'maxEndPaddingLen' => $t('Максимум дополнительных байтов в конце сегмента Mieru. 0 отключает это дополнение; сброс возвращает выбор ядра.',
                'Maximum extra bytes at the end of a Mieru segment. 0 disables this padding; reset restores the core\'s choice.'),
            'lowEntropy' => $t('Добавление битов-заполнителей к зашифрованному трафику Mieru для снижения его внешней случайности. Размер передаваемого тела увеличивается.',
                'Adding filler bits to encrypted Mieru traffic to lower its apparent randomness. The transferred body grows.'),
            'mode' => $t('Доля полезных битов в каждом 64-битном блоке Mieru: OFF — без перекодирования; 32 — 32+32 бита (×2); 40 — 40+24 (×1,6); 48 — 48+16 (×1,33); 56 — 56+8 (×1,14). Меньше полезных битов — больше трафика.',
                'Share of payload bits in each 64-bit Mieru block: OFF: no re-encoding; 32: 32+32 bits (×2); 40: 40+24 (×1.6); 48: 48+16 (×1.33); 56: 56+8 (×1.14). Fewer payload bits mean more traffic.'),
            'maskRotation' => $t('Поворот маски битов-заполнителей между блоками Mieru. NO_ROTATION — без поворота; RIGHT_1…15 / LEFT_1…15 — вправо/влево на указанное число бит. Не действует при выключенном lowEntropy.',
                'Rotation of the filler bit mask between Mieru blocks. NO_ROTATION: no rotation; RIGHT_1…15 / LEFT_1…15: right/left by the given number of bits. No effect with lowEntropy off.'),
            'multiplexing' => $t('Сколько логических соединений Mieru объединять в одном транспортном соединении. OFF — не объединять; LOW — мало, MIDDLE — средне, HIGH — много. Большее объединение экономит соединения, но усиливает их взаимное влияние.',
                'How many logical Mieru connections to combine in one transport connection. OFF: none; LOW: few, MIDDLE: medium, HIGH: many. More multiplexing saves connections but increases their mutual influence.'),
            'handshakeMode' => $t('HANDSHAKE_STANDARD — дождаться ответа сервера; HANDSHAKE_NO_WAIT — отправлять данные без этого ожидания. NO_WAIT уменьшает задержку старта, но результат авторизации станет известен позже.',
                'HANDSHAKE_STANDARD: wait for the server response; HANDSHAKE_NO_WAIT: send data without that wait. NO_WAIT cuts start latency, but the authentication result becomes known later.'),
            'socks5Port' => $t('Локальный SOCKS5-порт отдельного приложения Mieru на устройстве клиента. Не является внешним портом VPN-сервера.',
                'Local SOCKS5 port of the standalone Mieru app on the client device. It is not the external port of the VPN server.'),
            'rpcPort' => $t('Локальный управляющий RPC-порт отдельного приложения Mieru. Должен отличаться от SOCKS5 и HTTP-порта.',
                'Local control RPC port of the standalone Mieru app. Must differ from the SOCKS5 and HTTP ports.'),
            'httpProxyPort' => $t('Локальный HTTP-прокси порт отдельного приложения Mieru. Сброс убирает явную настройку этого порта; это не порт сервера.',
                'Local HTTP proxy port of the standalone Mieru app. Reset removes the explicit setting of this port; it is not the server port.'),
            default => '',
        };
        $choices = match ($field) {
            'fingerprint' => ['default' => $t('не задавать отпечаток в профиле; выбор клиента', 'do not set a fingerprint in the profile; the client decides'), 'chrome' => 'ClientHello Chrome',
                'firefox' => 'ClientHello Firefox', 'edge' => 'ClientHello Edge', 'safari' => 'ClientHello Safari', 'ios' => $t('ClientHello Safari на iOS', 'ClientHello Safari on iOS'),
                'random' => $t('случайный поддерживаемый отпечаток; выбор зависит от клиента', 'a random supported fingerprint; the choice depends on the client')],
            'ip-version' => ['dual' => $t('IPv4 и IPv6', 'IPv4 and IPv6'), 'ipv4' => $t('только IPv4', 'IPv4 only'), 'ipv6' => $t('только IPv6', 'IPv6 only'), 'ipv4-prefer' => $t('предпочесть IPv4', 'prefer IPv4'), 'ipv6-prefer' => $t('предпочесть IPv6', 'prefer IPv6')],
            'dualStack' => ['USE_FIRST_IP' => $t('первый адрес DNS', 'the first DNS address'), 'PREFER_IPv4' => $t('предпочесть IPv4', 'prefer IPv4'), 'PREFER_IPv6' => $t('предпочесть IPv6', 'prefer IPv6'), 'ONLY_IPv4' => $t('только IPv4', 'IPv4 only'), 'ONLY_IPv6' => $t('только IPv6', 'IPv6 only')],
            'bbr-profile' => ['standard' => $t('обычный баланс', 'ordinary balance'), 'conservative' => $t('менее агрессивное увеличение скорости', 'less aggressive speed increase'), 'aggressive' => $t('более агрессивный набор скорости, возможны очереди и потери', 'more aggressive ramp-up; queues and losses are possible')],
            'type' => ['NONCE_TYPE_RANDOM' => $t('оставить случайные байты', 'keep random bytes'), 'NONCE_TYPE_PRINTABLE' => $t('печатные ASCII-символы', 'printable ASCII characters'), 'NONCE_TYPE_PRINTABLE_SUBSET' => $t('ограниченный набор печатных символов', 'a limited set of printable characters'), 'NONCE_TYPE_FIXED' => $t('префикс из customHexStrings', 'a prefix from customHexStrings')],
            'spoof_method' => ['wrong-sequence' => $t('номер TCP вне окна приёма', 'a TCP sequence number outside the receive window'), 'wrong-checksum' => $t('неверная контрольная сумма TCP', 'a wrong TCP checksum'), 'wrong-ack' => $t('неверный номер подтверждения', 'a wrong acknowledgement number'), 'wrong-md5' => $t('неприемлемая TCP-MD5 подпись', 'an unacceptable TCP-MD5 signature'), 'wrong-timestamp' => $t('устаревшая TCP-метка времени; не поддерживается на macOS', 'a stale TCP timestamp; not supported on macOS')],
            default => [],
        };
        foreach ($choices as $value => $meaning) $text .= "\n$value — $meaning.";
        return $text;
    }
}
